export interface CirclebackConfig {
  /** Stable account/installation namespace. Use a new sourceId when changing accounts or filters. */
  sourceId: string
  /** Schema setup only; runtime pipeline factories do not change raw tables. */
  database: string
  ownership: 'All' | 'Mine' | 'Shared'
}

export type CirclebackReaderConfig = Omit<CirclebackConfig, 'database'>

// Credentials are read at request time; collections are fully revisited on every run.
export const circlebackConfig: CirclebackConfig = {
  sourceId: 'circleback',
  database: 'default',
  ownership: 'All',
}

import { HttpError, IngestConfigError, paginate, rawRows, type ErrorClassifier, type FetchContext } from '@chkit/plugin-ingest'

import { circlebackConfig, type CirclebackReaderConfig } from './config.js'

const baseUrl = 'https://circleback.ai/api'
export type CirclebackObject = Record<string, unknown>

export interface CirclebackClientDeps {
  config: CirclebackReaderConfig
  fetch: (url: string, init: RequestInit) => Promise<Response>
  token: () => string | undefined
}

export const defaultCirclebackClientDeps: CirclebackClientDeps = {
  config: circlebackConfig,
  fetch: (url, init) => fetch(url, init),
  token: () => process.env.CIRCLEBACK_API_KEY,
}

/** The executor owns one request attempt per page; Link cursors remain local to the full read. */
export function readCirclebackPages(context: FetchContext, collection: {
  path: '/meetings' | '/action-items' | '/people' | '/companies'
  query?: Record<string, string>
}, deps: CirclebackClientDeps) {
  const initial = new URL(`${baseUrl}${collection.path}`)
  for (const [key, value] of Object.entries(collection.query ?? {})) initial.searchParams.set(key, value)
  return paginate<CirclebackObject, string>({
    context, initial: initial.toString(), label: `GET ${collection.path}`,
    fetchPage: async (url, signal) => {
      if (!url) throw new IngestConfigError('Circleback collection URL is missing.')
      const response = await requestCircleback(url, signal, deps)
      const body: unknown = await response.json()
      if (!Array.isArray(body)) throw new IngestConfigError(`Circleback ${collection.path} is not an array.`)
      return { items: body.map((item: unknown) => requireCirclebackObject(item, collection.path)),
        next: nextLink(response.headers.get('link'), url, collection.query ?? {}) }
    },
  })
}

export async function requestCircleback(pathOrUrl: string, signal: AbortSignal, deps: CirclebackClientDeps, allowUnavailable = false): Promise<Response> {
  const token = deps.token()?.trim()
  if (!token) throw new IngestConfigError('Set CIRCLEBACK_API_KEY.')
  const response = await deps.fetch(pathOrUrl.startsWith('/') ? `${baseUrl}${pathOrUrl}` : pathOrUrl, {
    signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), redirect: 'error',
    headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
  })
  if (allowUnavailable && (response.status === 403 || response.status === 404)) return response
  if (!response.ok) throw await HttpError.fromResponse(response)
  return response
}

export function classifyCirclebackError(cause: unknown): ReturnType<ErrorClassifier> {
  return cause instanceof SyntaxError ? { kind: 'permanent' } : undefined
}

export function toCirclebackRows(items: readonly CirclebackObject[], id: (item: CirclebackObject) => string | number, sourceId: string) {
  return rawRows(items.map((data) => ({ source_id: sourceId, data })), (item) => JSON.stringify([sourceId, id(item.data)]))
}

/** Tag names are the requested projection; provider objects otherwise stay intact. */
export function tagNames(item: CirclebackObject): CirclebackObject {
  if (item.tags === undefined) return item
  if (!Array.isArray(item.tags)) throw new IngestConfigError('Circleback tags is not an array.')
  return { ...item, tags: item.tags.map((tag: unknown) => {
    const name = requireCirclebackObject(tag, 'tag').name
    if (typeof name !== 'string' || !name.trim()) throw new IngestConfigError('Circleback tag has no name.')
    return name
  }) }
}

export function requireCirclebackObject(value: unknown, label: string): CirclebackObject {
  if (!isCirclebackObject(value)) throw new IngestConfigError(`Circleback ${label} is not an object.`)
  return value
}

export function meetingId(item: CirclebackObject): string {
  if (typeof item.id !== 'string' || !item.id.trim()) throw new IngestConfigError('Circleback meeting has no valid ID.')
  return item.id
}

export function numericId(value: unknown, label: string): number {
  if (typeof value !== 'number' || !Number.isSafeInteger(value) || value <= 0) throw new IngestConfigError(`Circleback ${label} has no valid numeric ID.`)
  return value
}

function isCirclebackObject(value: unknown): value is CirclebackObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function nextLink(header: string | null, current: string, query: Record<string, string>): string | undefined {
  if (!header?.trim()) return undefined
  const candidates: string[] = []
  for (const part of header.split(/,(?=\s*<)/)) {
    const link = /^\s*<([^>]+)>\s*(.*)$/.exec(part)
    if (!link) throw new IngestConfigError('Circleback returned a malformed Link header.')
    const relation = /;\s*rel\s*=\s*(?:"([^"]+)"|([^;\s]+))/.exec(link[2] ?? '')
    if (!(relation?.[1] ?? relation?.[2])?.split(/\s+/).includes('next')) continue
    if (!link[1]) throw new IngestConfigError('Circleback next page URL is missing.')
    candidates.push(link[1])
  }
  if (candidates.length > 1) throw new IngestConfigError('Circleback returned multiple next pages.')
  const value = candidates[0]
  if (!value) return undefined
  let next: URL
  try { next = new URL(value, current) }
  catch { throw new IngestConfigError('Circleback returned an invalid next page URL.') }
  if (next.origin !== 'https://circleback.ai' || next.pathname !== new URL(current).pathname || next.username || next.password || next.hash) {
    throw new IngestConfigError('Circleback next page changed the collection or origin.')
  }
  for (const [key, value] of Object.entries(query)) {
    const values = next.searchParams.getAll(key)
    if (values.length > 1 || values.some((nextValue) => nextValue !== value)) {
      throw new IngestConfigError(`Circleback next page changed the ${key} filter.`)
    }
    next.searchParams.set(key, value)
  }
  return next.toString()
}

import { definePipeline, defineStream, fullSync, IngestConfigError } from '@chkit/plugin-ingest'

import { classifyCirclebackError, defaultCirclebackClientDeps, type CirclebackClientDeps } from './client.js'
import { circlebackConfig, type CirclebackReaderConfig } from './config.js'
import { circleback_meetingsRaw, readMeetings } from './sources/meetings.js'
import { circleback_meetingTranscriptsRaw, readMeetingTranscripts } from './sources/meeting-transcripts.js'
import { circleback_actionItemsRaw, readActionItems } from './sources/action-items.js'
import { circleback_peopleRaw, readPeople } from './sources/people.js'
import { circleback_companiesRaw, readCompanies } from './sources/companies.js'

export function createCirclebackPipeline(config: CirclebackReaderConfig = circlebackConfig, deps: CirclebackClientDeps = defaultCirclebackClientDeps) {
  if (!config.sourceId.trim() || !['All', 'Mine', 'Shared'].includes(config.ownership)) {
    throw new IngestConfigError('Circleback needs a sourceId and valid meeting ownership.')
  }
  const source = { ...config }, client = { ...deps, config: source }
  const options = { incremental: fullSync(), classifyError: classifyCirclebackError }
  return definePipeline({
    id: source.sourceId, tags: ['provider:circleback'], maxStreams: 1, maxFetches: 1,
    streams: [
      defineStream({ ...options, id: `${source.sourceId}.meetings`, tags: ['resource:meetings'], destination: circleback_meetingsRaw,
        read: (context) => readMeetings(context, client) }),
      defineStream({ ...options, id: `${source.sourceId}.meeting_transcripts`, tags: ['resource:meeting_transcripts'], destination: circleback_meetingTranscriptsRaw,
        read: (context) => readMeetingTranscripts(context, client) }),
      defineStream({ ...options, id: `${source.sourceId}.action_items`, tags: ['resource:action_items'], destination: circleback_actionItemsRaw,
        read: (context) => readActionItems(context, client) }),
      defineStream({ ...options, id: `${source.sourceId}.people`, tags: ['resource:people'], destination: circleback_peopleRaw,
        read: (context) => readPeople(context, client) }),
      defineStream({ ...options, id: `${source.sourceId}.companies`, tags: ['resource:companies'], destination: circleback_companiesRaw,
        read: (context) => readCompanies(context, client) }),
    ],
  })
}

export const circlebackPipeline = createCirclebackPipeline()

import { rawTable, type FetchContext } from '@chkit/plugin-ingest'

import { meetingId, readCirclebackPages, tagNames, toCirclebackRows, type CirclebackClientDeps } from '../client.js'
import { circlebackConfig } from '../config.js'

export const circleback_meetingsRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_meetings_raw' })

export async function* readMeetings(context: FetchContext, deps: CirclebackClientDeps) {
  for await (const page of readCirclebackPages(context, { path: '/meetings', query: { ownership: deps.config.ownership } }, deps)) {
    yield { rows: toCirclebackRows(page.items.map(tagNames), meetingId, deps.config.sourceId) }
  }
}

import { IngestConfigError, rawRows, rawTable, type FetchContext } from '@chkit/plugin-ingest'

import { meetingId, readCirclebackPages, requestCircleback, requireCirclebackObject, type CirclebackClientDeps, type CirclebackObject } from '../client.js'
import { circlebackConfig } from '../config.js'

export const circleback_meetingTranscriptsRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_meeting_transcripts_raw' })

/** Discover every eligible meeting here: old meetings can gain transcripts without metadata changes. */
export async function* readMeetingTranscripts(context: FetchContext, deps: CirclebackClientDeps) {
  for await (const page of readCirclebackPages(context, { path: '/meetings', query: { ownership: deps.config.ownership } }, deps)) {
    for (const meeting of page.items) {
      const id = meetingId(meeting)
      const snapshot = await context.attempt(async (signal) => {
        const response = await requestCircleback(`/meeting/${encodeURIComponent(id)}/transcript`, signal, deps, true)
        if (response.status === 403) return { meeting_id: id, status: 'forbidden', data: null }
        if (response.status === 404) return { meeting_id: id, status: 'not_found', data: null }
        const transcript: unknown = await response.json()
        if (!Array.isArray(transcript)) throw new IngestConfigError('Circleback transcript is not an array.')
        const data = transcript.map((value: unknown) => {
          const segment = requireCirclebackObject(value, 'transcript segment')
          if ((segment.speaker !== null && typeof segment.speaker !== 'string') || typeof segment.text !== 'string' ||
            typeof segment.timestamp !== 'number' || !Number.isFinite(segment.timestamp)) {
            throw new IngestConfigError('Circleback returned an invalid transcript segment.')
          }
          return segment
        })
        return { meeting_id: id, status: 'available', data }
      }, { label: 'GET /meeting/{meetingId}/transcript' })
      const observations: CirclebackObject[] = [{ source_id: deps.config.sourceId, meeting_id: id, kind: 'availability', status: snapshot.status }]
      if (snapshot.status === 'available') observations.unshift({ source_id: deps.config.sourceId, kind: 'transcript', ...snapshot })
      // Unavailability changes read evidence, not the last successful transcript snapshot.
      yield { rows: rawRows(observations, (item) => JSON.stringify(item.kind === 'transcript'
        ? [deps.config.sourceId, id] : [deps.config.sourceId, id, 'availability'])) }
    }
  }
}

import { IngestConfigError, rawTable, type FetchContext } from '@chkit/plugin-ingest'

import { numericId, readCirclebackPages, tagNames, toCirclebackRows, type CirclebackClientDeps } from '../client.js'
import { circlebackConfig } from '../config.js'

// The official OpenAPI and Circleback CLI enumerate exactly these native completion statuses.
const statuses = ['PENDING', 'DONE']

export const circleback_actionItemsRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_action_items_raw' })

export async function* readActionItems(context: FetchContext, deps: CirclebackClientDeps) {
  for (const status of statuses) {
    for await (const page of readCirclebackPages(context, { path: '/action-items', query: { assigneeType: 'Anyone', status } }, deps)) {
      for (const item of page.items) {
        if (item.status !== status || !Array.isArray(item.meetingIds) ||
          !item.meetingIds.every((id: unknown) => typeof id === 'string' && id.trim())) {
          throw new IngestConfigError('Circleback action item has an unexpected status or invalid meeting IDs.')
        }
      }
      yield { rows: toCirclebackRows(page.items.map(tagNames), (item) => numericId(item.id, 'action item'), deps.config.sourceId) }
    }
  }
}

import { IngestConfigError, rawTable, type FetchContext } from '@chkit/plugin-ingest'

import { numericId, readCirclebackPages, requestCircleback, requireCirclebackObject, tagNames, toCirclebackRows, type CirclebackClientDeps } from '../client.js'
import { circlebackConfig } from '../config.js'

export const circleback_peopleRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_people_raw' })

export async function* readPeople(context: FetchContext, deps: CirclebackClientDeps) {
  for await (const page of readCirclebackPages(context, { path: '/people' }, deps)) {
    for (const listed of page.items) {
      const id = numericId(listed.id, 'person')
      const detail = await context.attempt(async (signal) => {
        const response = await requestCircleback(`/person/${id}`, signal, deps)
        const person = requireCirclebackObject(await response.json(), 'person detail')
        if (numericId(person.id, 'person detail') !== id || !Array.isArray(person.externalLinks)) {
          throw new IngestConfigError('Circleback person detail changed its ID or omitted external links.')
        }
        return person
      }, { label: 'GET /person/{profileId}' })
      yield { rows: toCirclebackRows([tagNames({ ...listed, ...detail })], (item) => numericId(item.id, 'person'), deps.config.sourceId) }
    }
  }
}

import { IngestConfigError, rawRows, rawTable, type FetchContext } from '@chkit/plugin-ingest'

import { numericId, readCirclebackPages, requestCircleback, requireCirclebackObject, tagNames, type CirclebackClientDeps, type CirclebackObject } from '../client.js'
import { circlebackConfig } from '../config.js'

export const circleback_companiesRaw = rawTable({ database: circlebackConfig.database, name: 'circleback_companies_raw' })

export async function* readCompanies(context: FetchContext, deps: CirclebackClientDeps) {
  for await (const page of readCirclebackPages(context, { path: '/companies' }, deps)) {
    for (const listed of page.items) {
      const domain = companyDomain(listed)
      const detail = await context.attempt(async (signal) => {
        const response = await requestCircleback(`/company/${encodeURIComponent(domain)}`, signal, deps)
        return requireCirclebackObject(await response.json(), 'company detail')
      }, { label: 'GET /company/{domain}' })
      if (companyDomain(detail) !== domain || !Array.isArray(detail.people) || !Array.isArray(detail.externalLinks)) {
        throw new IngestConfigError('Circleback company detail changed its domain or omitted people/external links.')
      }
      const companyIds = new Set<number>()
      for (const item of [listed, detail]) {
        if (item.id !== undefined) companyIds.add(numericId(item.id, 'company'))
      }
      for (const value of detail.people) {
        const person = requireCirclebackObject(value, 'company person')
        numericId(person.id, 'company person')
        if (person.companyId !== null) companyIds.add(numericId(person.companyId, 'person company'))
      }
      if (companyIds.size > 1) throw new IngestConfigError('Circleback company returned conflicting numeric company IDs.')
      const snapshot = { source_id: deps.config.sourceId, company_id: [...companyIds][0] ?? null, data: tagNames({ ...listed, ...detail }) }
      // The provider domain is always the identity, even when an optional numeric ID appears later.
      yield { rows: rawRows([snapshot], () => JSON.stringify([deps.config.sourceId, domain])) }
    }
  }
}

function companyDomain(item: CirclebackObject): string {
  if (typeof item.domain !== 'string' || !item.domain.trim()) throw new IngestConfigError('Circleback company has no domain.')
  return item.domain
}

import { expect, test } from 'bun:test'
import { IngestConfigError, runIngestion, selectStreams } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal } from '@chkit/plugin-ingest/testing'

import { createCirclebackPipeline, circlebackPipeline } from '../index.js'
import { circlebackConfig, type CirclebackConfig } from '../config.js'
import { defaultCirclebackClientDeps } from '../client.js'

const cutoff = new Date('2026-01-02T00:00:00Z')
const resources = ['meetings', 'meeting_transcripts', 'action_items', 'people', 'companies']
const meeting = { id: 'meeting-a', name: 'Old meeting', updatedAt: '2020-01-01T00:00:00Z', notes: 'Provider notes',
  tags: [{ id: 10, name: 'Customer' }, { id: 11, name: 'Follow up' }], attendees: [{ profileId: 1 }],
  actionItems: [{ id: 252, status: 'PENDING' }], custom: { retained: true } }
const transcript = [{ speaker: null, text: 'Full transcript\nwith another line', timestamp: 0.25, custom: true }]
const pending = { id: 252, title: 'Follow up', status: 'PENDING', completedAt: null, assignee: { profileId: 1 }, meetingIds: ['meeting-a'], custom: true }
const done = { id: 253, title: 'Completed work', status: 'DONE', completedAt: '2020-01-01T00:00:00Z', assignee: null, meetingIds: [], custom: true }
const person = { id: 1, companyId: 3, firstName: 'John', lastName: 'Appleseed', email: 'john@initech.com', companyName: 'Initech', title: 'Operations', custom: true }
const personDetail = { ...person, externalLinks: [{ type: 'linkedin', objectType: 'person', url: 'https://www.linkedin.com/in/john-appleseed' }] }
const company = { domain: 'initech.com', name: 'Initech', avatarUrl: null, custom: true }
const companyDetail = { ...company, people: [person], externalLinks: [{ type: 'website', objectType: 'company', url: 'https://initech.com' }] }

type Pipeline = ReturnType<typeof createCirclebackPipeline>
type Responder = (url: URL, init: RequestInit) => Response | Promise<Response>

test('Circleback publishes five raw resources with scoped native IDs and string tag names', async () => {
  const calls: URL[] = [], pipeline = fixturePipeline((url, init) => { calls.push(url); return fixtureResponse(url, init) })
  expect(circlebackPipeline.streams).toHaveLength(5)
  expect(pipeline.streams.map((stream) => stream.id).sort()).toEqual(resources.map((resource) => `circleback.${resource}`).sort())
  const journal = createMemoryJournal(), destination = createMemoryDestination()
  const result = await runIngestion(request(pipeline), { journal, destination, now: () => cutoff })
  expect(result.ok, JSON.stringify(result)).toBe(true)
  const expected = {
    meetings: [{ id: rowId('meeting-a'), raw: envelope({ ...meeting, tags: ['Customer', 'Follow up'] }) }],
    meeting_transcripts: [
      { id: rowId('meeting-a'), raw: { source_id: 'circleback', kind: 'transcript', meeting_id: 'meeting-a', status: 'available', data: transcript } },
      { id: JSON.stringify(['circleback', 'meeting-a', 'availability']), raw: { source_id: 'circleback', meeting_id: 'meeting-a', kind: 'availability', status: 'available' } },
    ],
    action_items: [pending, done].map((data) => ({ id: rowId(data.id), raw: envelope(data) })),
    people: [{ id: rowId(person.id), raw: envelope(personDetail) }],
    companies: [{ id: rowId(company.domain), raw: { source_id: 'circleback', company_id: 3, data: companyDetail } }],
  }
  expect(destination.tables.size).toBe(5)
  for (const [resource, rows] of Object.entries(expected)) {
    expect(destination.tables.get(`default.circleback_${resource}_raw`)?.map(({ id, raw }) => ({ id, raw }))).toEqual(rows)
    expect((await journal.readCheckpoint(`circleback.${resource}`)).envelope).toBeUndefined()
    expect((await journal.readCheckpoint(`circleback.${resource}`)).lastSuccessSeq).toBeGreaterThan(0)
  }
  expect(calls.some((url) => url.pathname.includes('/calendar') || url.pathname.includes('/tags') || url.hostname !== 'circleback.ai')).toBe(false)
})

test('all resources run alone and reversing stream order preserves their raw observations', async () => {
  const pipeline = fixturePipeline(), combined = createMemoryDestination()
  expect((await runIngestion(request({ ...pipeline, streams: [...pipeline.streams].reverse() }),
    { journal: createMemoryJournal(), destination: combined, now: () => cutoff })).ok).toBe(true)
  for (const resource of resources) {
    const calls: URL[] = [], destination = createMemoryDestination()
    const isolated = fixturePipeline((url, init) => { calls.push(url); return fixtureResponse(url, init) })
    const selected = request(isolated, resource)
    expect(selected.selected.map((entry) => entry.stream.id)).toEqual([`circleback.${resource}`])
    expect((await runIngestion(selected, { journal: createMemoryJournal(), destination, now: () => cutoff })).ok).toBe(true)
    expect(destination.tables.size).toBe(1)
    expect(destination.tables.get(`default.circleback_${resource}_raw`)?.map(({ id, raw }) => ({ id, raw })))
      .toEqual(combined.tables.get(`default.circleback_${resource}_raw`)?.map(({ id, raw }) => ({ id, raw })))
    expect(calls).toHaveLength(resource === 'meetings' ? 1 : 2)
    if (resource === 'meetings') expect(calls.map((url) => url.pathname)).toEqual(['/api/meetings'])
    if (resource === 'action_items') expect(calls.every((url) => url.pathname === '/api/action-items')).toBe(true)
    if (resource === 'companies') expect(calls.map((url) => url.pathname)).toEqual(['/api/companies', '/api/company/initech.com'])
    if (resource === 'people') expect(calls.map((url) => url.pathname)).toEqual(['/api/people', '/api/person/1'])
  }
})

test('action items enumerate both native completion statuses for anyone and follow each partition to exhaustion', async () => {
  const calls: URL[] = []
  const pipeline = fixturePipeline((url) => {
    calls.push(url)
    expect(url.searchParams.get('assigneeType')).toBe('Anyone')
    const status = url.searchParams.get('status')
    expect(status === 'PENDING' || status === 'DONE').toBe(true)
    const item = status === 'PENDING' ? pending : done
    if (url.searchParams.has('cursor')) return Response.json([{ ...item, id: item.id + 10 }])
    return Response.json([item], { headers: { Link: `</api/action-items?assigneeType=Anyone&status=${status}&cursor=next>; rel="next"` } })
  })
  const journal = createMemoryJournal(), destination = createMemoryDestination()
  expect((await runIngestion(request(pipeline, 'action_items'), { journal, destination, now: () => cutoff })).ok).toBe(true)
  expect(calls.map((url) => [url.searchParams.get('status'), url.searchParams.get('cursor')])).toEqual([
    ['PENDING', null], ['PENDING', 'next'], ['DONE', null], ['DONE', 'next'],
  ])
  expect(destination.tables.get('default.circleback_action_items_raw')?.map((row) => row.id)).toEqual([252, 262, 253, 263].map((id) => rowId(id)))
  expect((await journal.readCheckpoint('circleback.action_items')).lastSuccessSeq).toBeGreaterThan(0)
})

test('cursor-only continuations retain ownership and completion filters and conflicting links fail visibly', async () => {
  for (const resource of ['meetings', 'action_items']) {
    const calls: URL[] = []
    const pipeline = fixturePipeline((url) => {
      calls.push(url)
      if (resource === 'action_items' && url.searchParams.get('status') === 'PENDING') return Response.json([])
      if (url.searchParams.has('cursor')) return Response.json(resource === 'meetings' ? [meeting] : [done])
      return Response.json([], { headers: { Link: `<${url.pathname}?cursor=next>; rel="next"` } })
    })
    expect((await runIngestion(request(pipeline, resource), { journal: createMemoryJournal(), destination: createMemoryDestination(), now: () => cutoff })).ok).toBe(true)
    const continued = calls.at(-1)
    expect(continued?.searchParams.get('cursor')).toBe('next')
    if (resource === 'meetings') expect(continued?.searchParams.get('ownership')).toBe('All')
    else {
      expect(continued?.searchParams.get('status')).toBe('DONE')
      expect(continued?.searchParams.get('assigneeType')).toBe('Anyone')
    }
  }
  for (const [resource, conflict] of [['meetings', 'ownership=Mine'], ['action_items', 'status=DONE'], ['action_items', 'assigneeType=Me']] satisfies [string, string][]) {
    let calls = 0
    const pipeline = fixturePipeline((url) => {
      calls++
      return Response.json([], { headers: { Link: `<${url.pathname}?cursor=next&${conflict}>; rel="next"` } })
    })
    const journal = createMemoryJournal()
    expect((await runIngestion(request(pipeline, resource), { journal, destination: createMemoryDestination(), now: () => cutoff })).ok).toBe(false)
    expect(calls).toBe(1)
    expect((await journal.readCheckpoint(`circleback.${resource}`)).lastSuccessSeq).toBe(0)
  }
})

test('late transcripts on unchanged old meetings are revisited without running the meetings stream', async () => {
  let available = false
  const starts: string[] = [], calls: string[] = []
  const pipeline = fixturePipeline((url) => {
    calls.push(url.pathname)
    if (url.pathname.endsWith('/transcript')) {
      if (!available) return new Response('unavailable', { status: url.pathname.includes('/meeting-a/') ? 403 : 404 })
      return Response.json(url.pathname.includes('/meeting-a/') ? transcript : [])
    }
    starts.push(url.search)
    return Response.json([meeting, { ...meeting, id: 'meeting-b' }])
  })
  const journal = createMemoryJournal(), destination = createMemoryDestination(), selected = request(pipeline, 'meeting_transcripts')
